import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"04 | 使用LLM提取和传递知识","description":"","frontmatter":{},"headers":[{"level":2,"title":"LLM 是革命性的迁移学习平台","slug":"llm-是革命性的迁移学习平台","link":"#llm-是革命性的迁移学习平台","children":[]},{"level":2,"title":"聚焦于知识而非任务","slug":"聚焦于知识而非任务","link":"#聚焦于知识而非任务","children":[]},{"level":2,"title":"通过 LLM 提取与传递知识","slug":"通过-llm-提取与传递知识","link":"#通过-llm-提取与传递知识","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·AI时代的软件工程/04｜使用LLM提取和传递知识.md","filePath":"徐昊·AI时代的软件工程/04｜使用LLM提取和传递知识.md","lastUpdated":1795556403000}'),i={name:"徐昊·AI时代的软件工程/04｜使用LLM提取和传递知识.md"};function t(l,s,o,c,h,g){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_04-使用llm提取和传递知识" tabindex="-1">04 | 使用LLM提取和传递知识 <a class="header-anchor" href="#_04-使用llm提取和传递知识" aria-label="Permalink to &quot;04 | 使用LLM提取和传递知识&quot;">​</a></h1><p>你好，我是徐昊，今天我们来继续学习 AI 时代的软件工程。</p><p>通过前面的学习，我们逐步认识了知识工程的整体框架，并且尝试用知识工程的视角重新理解软件工程，那么软件工程效率提升的问题，自然就转化成为构造知识传递效率更高的知识过程。</p><p>那么大语言模型（Large Language Model，LLM）能否让知识过程更高效呢？这就是今天我们要讨论的问题，因为这是将大语言模型（Large Language Model，LLM）应用到知识过程的前提条件。</p><h2 id="llm-是革命性的迁移学习平台" tabindex="-1">LLM 是革命性的迁移学习平台 <a class="header-anchor" href="#llm-是革命性的迁移学习平台" aria-label="Permalink to &quot;LLM 是革命性的迁移学习平台&quot;">​</a></h2><p>LLM 是怎么帮助我们提取知识的呢？我们首先需要将 LLM 看作一种特殊的迁移学习（Transfer Learning）平台。</p><p>迁移学习（Transfer Learning）是机器学习领域的一个重要概念，意思是将从一个问题（源任务）中学到的知识应用到另一个相关的问题（目标任务）上。即使两个任务不完全相同，一个任务中学到的特征、模式和知识也可以在另一个任务中发挥作用，从而提高学习效率和性能。比如，一个可以识别猫狗的计算机视觉 AI，可以通过迁移学习训练成用来识别汽车的 AI。</p><p>迁移学习在实际应用中非常重要，特别是在数据稀缺的情况下。例如，在深度学习中，训练一个从头开始的模型通常需要大量的标记数据和计算资源。通过迁移学习，我们可以利用在大型数据集上预训练的模型，然后将这些模型调整（fine-tune）到特定的、数据较少的任务上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/1.png" alt=""></a></p><ul><li>从头训练与迁移学习</li></ul><p>LLM 是一个非常特殊的模型，它的核心能力是阅读理解——结合预训练集中的语料，根据提示词中提供的上下文信息执行任务。从概念上说，当我们为 LLM 提供了上下文之后，实际已经把 LLM 迁移成为一个面向特定领域的模型了。</p><p>回想一下我们在开篇词中提过的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息；</span></span>
<span class="line"><span>此API包含列出所有商品，按SKU查看某个商品，按照分类列出商品以及按关键词搜索的功能；</span></span>
<span class="line"><span>API返回的结果是json格式；</span></span>
<span class="line"><span>当查找的SKU不存在时，返回404；</span></span>
<span class="line"><span>按关键搜索功能使用POST而不是GET；</span></span>
<span class="line"><span>使用Java编写；</span></span></code></pre></div><ul><li>为所有功能提供功能测试，包括异常情况。请编写功能和测试代码。</li></ul><p>这其中包含了上下文描述和问题 / 任务两个部分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息；(业务上下文)</span></span>
<span class="line"><span>此API包含列出所有商品，按SKU查看某个商品，按照分类列出商品以及按关键词搜索的功能；（业务功能描述）</span></span>
<span class="line"><span>API返回的结果是json格式；(技术规范描述）</span></span>
<span class="line"><span>当查找的SKU不存在时，返回404；(技术规范描述）</span></span>
<span class="line"><span>按关键搜索功能使用POST而不是GET；（最佳实践）</span></span>
<span class="line"><span>使用Java编写；（技术栈）</span></span></code></pre></div><ul><li>为所有功能提供功能测试，包括异常情况；（代码范围）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请编写功能和测试代码。（问题/任务）</span></span></code></pre></div><p>在概念上，如果将提示词中的上下文与问题当作截然不同的两个部分，那么实际上我们可以将结合了上下文的 LLM 看作一个经过迁移学习后的模型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/2.png" alt=""></a></p><ul><li>在概念上将 LLM 看作迁移学习</li></ul><p>之所以可以这样看待大模型，是因为 LLM 在大规模数据集上进行预训练，能够学习到语言的深层结构和模式，因此具备了很强的泛化能力。</p><p>这意味着 LLM 可以很容易地适应新的任务和领域，即使这些任务和领域在预训练时没有明确地被考虑进去。伴随着泛化能力，目前很多 LLM 支持零样本（zero-shot）或少样本（few-shot）学习。这意味着即使没有数据训练，或者只有很少的数据的情况下，LLM 也可以执行特定任务。</p><p>零样本或少样本学习是一种革命性的迁移学习机制。比起传统迁移学习，训练数据从几千几万条降低到零或几条。训练时间从几天、几周甚至几个月缩短到几秒钟或者几分钟。</p><p>我们在提示词中对于上下文的描述，实际上是在使用零样本学习对 LLM 进行迁移学习训练。将 LLM 看作一种特殊的迁移学习（Transfer Learning）平台是通过 LLM 提取知识的关键，提醒我们需要将用以迁移的上下文和具体的任务分开来看待。</p><h2 id="聚焦于知识而非任务" tabindex="-1">聚焦于知识而非任务 <a class="header-anchor" href="#聚焦于知识而非任务" aria-label="Permalink to &quot;聚焦于知识而非任务&quot;">​</a></h2><p>请你回想一下我们在开篇词中提到的例子，它最开始的版本是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息。此API不能修改或增加可售商品。</span></span></code></pre></div><ul><li>请提供代码和所有功能的功能测试。</li></ul><p>在这个提示词中，主要描述的是任务本身，也就是我们希望 LLM 帮助我们做什么，对于上下文和知识的描述是非常粗略的。此刻我们的关注点聚焦在 LLM 能做什么，寄希望于大模型的预训练恰好能够帮助我们补足上下文。</p><p>这其实是过往时代和经验带来的局限，我们习惯性地认为，将某个工作实际做出来是非常花费时间的，那么越早开始越好。但是在 LLM 时代，做出来的成本是非常低的，做对的成本是非常高的。因而，用好 LLM 的第一步，就是聚焦于知识的提取与组织。</p><p>我们可以把要做的事情放在一边，将目光更多的集中在如何迁移训练 LLM，也就是如何提取上下文、如何提取知识上。那么我们可以构造这样的一个提示词：</p><ul><li>背景</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息。</span></span>
<span class="line"><span>此API不能修改或增加可售商品。</span></span>
<span class="line"><span>使用Java编写。</span></span></code></pre></div><ul><li>任务</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span></code></pre></div><ul><li>请问这个产品目录服务主要有什么功能？</li></ul><p>我建议所有人在使用提示词的时候，都将知识的部分（背景）与任务的部分分开。这样能有一个明确的关注点。在这个改版的提示词中，我们暂时放弃了最终目标，而首先检查我们的知识提取是否足够清楚。ChatGPT 给我的答案是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/3.png" alt=""></a></p><p>显然，这个答案与我预期的结果是不同的，我们预期中这个 API 只有列出所有商品、按 SKU查看某个商品、按照分类列出商品以及按关键词搜索的功能。ChatGPT 列出了非常多的额外功能。如果在这个基础上去生产代码，就会有很多无用的功能。</p><p>那这说明什么呢？说明迁移学习的效果并不好，LLM 仍然受基础模型的影响，并没有完全迁移到我们现在要处理的领域。我们需要补充额外的信息，让 LLM 更接近我们要处理的领域。</p><p>我们可以补充这部分信息，然后使用同样的问题，再次询问 LLM：</p><ul><li>背景</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息。</span></span>
<span class="line"><span>此API包含列出所有商品，按SKU查看某个商品，按照分类列出商品以及按关键词搜索的功能；</span></span>
<span class="line"><span>使用Java编写。</span></span></code></pre></div><ul><li>任务</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span></code></pre></div><ul><li>请问这个产品目录服务主要有什么功能？</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/4.png" alt=""></a></p><p>这一次因为我们明确了功能的范围，ChatGPT 给出的答案就完全符合我们的要求了。同样，我们还可以继续验证当前的业务知识是否是足够的，比如：</p><ul><li>背景</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息。</span></span>
<span class="line"><span>此API包含列出所有商品，按SKU查看某个商品，按照分类列出商品以及按关键词搜索的功能；</span></span>
<span class="line"><span>使用Java编写。</span></span></code></pre></div><ul><li>任务</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>请问通过API提供的产品信息都包含哪些内容？</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/5.png" alt=""></a></p><p>同样 ChatGPT 提供了非常多的额外信息。如果在这个基础上去生产代码，还是会有很多无用的功能。因为我们这里是个例子，并没有细扣其中的具体实现细节，但是在实际工作中，我们可能会根据实际的情况，补充更完备的信息，比如：</p><ul><li>背景</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息。</span></span>
<span class="line"><span>商品详细信息包括：SKU，商品名字，不同的产品选项，以Markdown形式保存的商品详情；</span></span>
<span class="line"><span>此API包含列出所有商品，按SKU查看某个商品，按照分类列出商品以及按关键词搜索的功能；</span></span>
<span class="line"><span>使用Java编写。</span></span></code></pre></div><ul><li>任务</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>请问通过API提供的产品信息都包含哪些内容？</span></span></code></pre></div><p>当我们把目标聚焦于知识时，我们所关注的就不再仅仅是通过 LLM 帮助完成某些功能，而是如何使用 LLM 高质量地完成某些功能。</p><h2 id="通过-llm-提取与传递知识" tabindex="-1">通过 LLM 提取与传递知识 <a class="header-anchor" href="#通过-llm-提取与传递知识" aria-label="Permalink to &quot;通过 LLM 提取与传递知识&quot;">​</a></h2><p>这种通过 LLM 的反馈反思并修改知识描述的方式，就是知识工程中的知识提取流程，你可以结合下图来理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/6.png" alt=""></a></p><p>回想一下刚刚的例子，我们提取的是什么知识呢？我们提取的是隐式知识（ImplicitKnowledge）。因为对于业务的上下文我们已经有了构想和要求，只不过没有变成文字形式而已。</p><p>在提取了隐式知识之后，我们就可以在提取的知识之上，完成不同的任务了。这时候我们的关注点又从知识重新回到了任务。但此时我们会发现，提取出的知识并不仅仅能服务于某一项任务。在上面的例子里，虽然我们是为了编写代码而做的知识提取，但是产生的结果可以服务于其他任务。比如，为 API 编写文档：</p><ul><li>背景</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>目前我们在编写一个产品目录服务，通过API提供所有可售商品的详细信息。</span></span>
<span class="line"><span>商品详细信息包括：SKU，商品名字，不同的产品选项，以Markdown形式保存的商品详情；</span></span>
<span class="line"><span>此API包含列出所有商品，按SKU查看某个商品，按照分类列出商品以及按关键词搜索的功能；</span></span>
<span class="line"><span>使用Java编写。</span></span></code></pre></div><ul><li>要求</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span>
<span class="line"><span>所有API文档需要以RAML形式编写;</span></span>
<span class="line"><span>如存在异常分支，给出示例;</span></span></code></pre></div><ul><li>任务</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>===</span></span></code></pre></div><ul><li>根据背景中描述的业务，按要求编写文档</li></ul><p>当我们完成了知识提取，再将知识应用到具体的任务时，就是知识的传递和应用的过程。在知识工程中，知识的提取与传递流程如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/04/7.png" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天我们介绍了为什么要将 LLM 看作一个迁移学习平台，这样我们就可以将提示词中的上下文和任务赋予不同的意义。上下文负责迁移学习，而任务是要进行的操作。</p><p>然后我们沿用了开篇词里产品目录服务的例子，演示了如何提取上下文、如何提取知识。这里的重点是我们要聚焦在知识而非任务上，通过 LLM 来检验知识的收集与提炼是否充分。再把提取的知识与任务结合，完成知识的传递与应用。</p><p>通过 LLM 的辅助，利用知识与任务的分离，我们有效地收集和传递了显式化的隐式知识。但是对于知识过程中的核心——不可言说知识要怎么处理呢？我们下节课再继续讨论。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这节课例子演示了如何利用 LLM 提取隐式知识，那么对于不可言说知识，我们要怎么提炼和应用呢？</p><p>欢迎在留言区分享你的想法，我会让编辑置顶一些优质回答供大家学习讨论。</p>`,81)])])}const r=a(i,[["render",t]]);export{d as __pageData,r as default};
